struct Disk {std::array<uint8_t,65536> bytes{};int writes=-1;};
bool Block(void* raw,io::Op op,uint64_t offset,uint8_t* data) noexcept {auto& d=*static_cast<Disk*>(raw);if(op==io::Op::Write||op==io::Op::Flush){if(!d.writes)return false;if(d.writes>0)--d.writes;}if(op==io::Op::Flush)return true;if(!data||offset>65536-512||(offset&511))return false;if(op==io::Op::Read)std::memcpy(data,d.bytes.data()+offset,512);else if(op==io::Op::Write)std::memcpy(d.bytes.data()+offset,data,512);else return false;return true;}
struct Bridge {processes::Manager* p;threads::Scheduler* s;uint32_t child=0;};
uint32_t Start(void* raw,uint32_t parent,const char* image,uint32_t& child,uint64_t& handle) noexcept {auto& b=*static_cast<Bridge*>(raw);if(std::strcmp(image,"service.exe"))return processes::NotFound;auto st=b.p->CreateServiceProcess(parent,child);if(st)return st;const auto tid=b.s->CreateThread();uint64_t local=0,thread=0;st=b.p->Attach(child,tid,local);if(!st)st=b.p->ServiceHandles(parent,child,tid,handle,thread);if(st){b.p->Kill(child,st);b.p->Reap(child);child=0;return st;}b.p->Close(parent,thread);b.p->Close(child,local);b.child=child;return 0;}
security::Request Key(security::Op op,uint64_t root,const char* path=""){security::Request r;r.op=op;r.handle=root;r.access=0x7001F;std::strcpy(r.path,path);return r;}
void TransactionRecovery(const Disk& baseline,threads::Scheduler& scheduler,const processes::Token& admin){
    for(int prefix=0;prefix<=52;++prefix){auto disk=baseline;auto v=std::make_unique<storage::Volume>();v->Configure(&disk,Block,scheduler);Verify(!v->Mount());security::ServiceConfig config;std::strcpy(config.name,"failure");std::strcpy(config.image,"service.exe");char path[128]="HKLM\\System\\CurrentControlSet\\Services\\failure";disk.writes=prefix;const auto result=v->PersistRegistry(admin,path,"Config",&config,sizeof(config),false);disk.writes=-1;
        storage::Command c;c.op=storage::Op::RegGet;c.length=512;std::strcpy(c.path,path);std::strcpy(c.name,"Config");const auto inMemory=v->Execute(1,admin,c);Verify(result?inMemory==storage::NotFound:(!inMemory&&c.transferred==sizeof(config)));
        auto recovered=std::make_unique<storage::Volume>();recovered->Configure(&disk,Block,scheduler);Verify(!recovered->Mount());c={};c.op=storage::Op::RegGet;c.length=512;std::strcpy(c.path,path);std::strcpy(c.name,"Config");const auto durable=recovered->Execute(1,admin,c);Verify(durable==storage::NotFound||(!durable&&c.transferred==sizeof(config)&&!std::memcmp(c.data,&config,sizeof(config))));
        c={};c.op=storage::Op::RegGet;c.length=512;std::strcpy(c.path,"HKCU\\Software\\Aegis");std::strcpy(c.name,"answer");Verify(!recovered->Execute(1,admin,c)&&c.data[0]==42);
    }
}
